def main() -> int:
    root = Path(__file__).resolve().parent
    written, same = [], []
    for rel, want_sha, blob in FILES:
        data = base64.b64decode("".join(blob.split()))
        got = hashlib.sha256(data).hexdigest()[:12]
        if got != want_sha:
            print(f"CORRUPT  {rel} (expected {want_sha}, got {got})")
            return 1
        dest = root / rel
        if dest.exists() and dest.read_bytes() == data:
            same.append(rel)
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
        written.append(rel)

    for r in written:
        print(f"updated  {r}")
    for r in same:
        print(f"same     {r}")
    print(f"\n{len(written)} file(s) updated, {len(same)} already current.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
